import { button, esc, header } from './views.js';
import { icon } from './icons.js';
import { GOLF_COURSES, golfPar, golfHoleCount, courseRecordKey } from './golf-courses.js';
import { COURSES, getHole, relative } from './courses.js';
import { featuredCourses } from './rotating-courses.js';
export function courseMenu(ui) {
  const golf=ui.mode==='golf',courses=golf?GOLF_COURSES:COURSES;
  const card=(i,feature)=>{
    const c=courses[i],count=golf?golfHoleCount(i):9,unlocked=ui.localPreview||ui.progress.level.level>=c.level;
    const best=ui.progress.data.bests[courseRecordKey(ui.mode,i)],par=Array.from({length:count},(_,j)=>golf?golfPar(i,j):getHole(i,j).par).reduce((a,b)=>a+b,0);
    const reset=feature?.ends?new Date(feature.ends).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}):'';
    return `<article class="arcade-course ${i===18?'daily-volcano':''} ${feature?'featured-course':''}" data-course-card="${i}" data-card><img data-course-preview="${ui.mode}:${i}" src="${ui.world.thumbnail(i,ui.mode)}" alt="${esc(c.name)}" loading="lazy" decoding="async"><div class="arcade-course-copy"><div class="course-card-meta">${feature?`<span class="course-slot" title="${!feature.ends?'Always available':feature.label==='Seasonal course'?'Ends':i===18?'Daily score resets':'Changes'} ${esc(reset)}">${esc(feature.label)}</span>`:''}<span>${count} ${count===1?'hole':'holes'} · Par ${par}</span></div><${golf?'h3':'h2'}>${esc(c.name)}</${golf?'h3':'h2'}><p>${esc(c.subtitle)}</p><div class="arcade-course-record"><span>${unlocked?esc(c.difficulty):'Level '+c.level+' · Practice available'}</span><span>Best ${best?relative(best.score):'-'}</span></div>${button(icon('play')+(unlocked?'Play':'Practice'),unlocked?'start':'practice',`data-course="${i}" data-card-primary aria-label="${unlocked?'Play':'Practice'} ${esc(c.name)}"`,'arcade-button arcade-primary')}</div></article>`;
  };
  const features=featuredCourses(),allFeatures=features;
  const section=(id,num,title,note,body)=>`<section class="course-section course-section-${id}" aria-labelledby="${id}-courses-heading"><div class="course-section-heading"><div><span class="course-section-number">${num}</span><h2 id="${id}-courses-heading">${title}</h2></div><span>${note}</span></div>${body}</section>`;
  const grid=cards=>`<div class="arcade-courses" style="--course-count:${cards.length}">${cards.join('')}</div>`;
  const weekly=features.filter(f=>['Map of the week','Weekly sprint'].includes(f.label));
  const other=features.filter(f=>['Map of the month','Seasonal course'].includes(f.label));
  const content=golf?`<div class="course-sections">${section('full','01','Full Courses','Nine holes · Settle in for a full round',grid([14,15,16].map(i=>card(i))))}${section('blitz','02','Blitz Courses','Three holes · A quick round, a fresh challenge',grid([... [0,1,2].map(i=>card(i)),card(18,features.find(f=>f.index===18))]))}${section('other','03','Other Maps','Different worlds. More ways to play.',`${grid(other.map(f=>card(f.index,f)))}<div class="course-weekly-heading"><h3>Maps of the Week</h3><span>New picks every Monday · Includes the former daily sprint</span></div>${grid(weekly.map(f=>card(f.index,f)))}`)}</div>`:grid(courses.map((_,i)=>card(i)));
  return `${header(ui)}<main class="arcade-page course-menu ${golf?'full-golf-menu':''}"><header class="arcade-page-header"><div class="course-page-title"><span class="eyebrow">FIND YOUR FAIRWAY</span><h1>Pick your next round.</h1><p>Nine-hole journeys, quick rounds and worlds worth exploring.</p></div>${button(`<span>${icon('flag')}<strong>Community Maps</strong><small>Explore courses made by players</small></span><b aria-hidden="true">↗</b>`,'community','','arcade-button community-map-link')}</header><section class="arcade-page-content"><nav class="arcade-switch" aria-label="Golf mode">${[['golf','Full golf'],['mini','Mini-golf']].map(([id,label])=>button(label,'mode',`data-id="${id}" aria-pressed="${ui.mode===id}"`,'arcade-button')).join('')}${golf?`<span class="course-menu-note">${allFeatures.length+3} courses · Scroll to explore</span>`:''}</nav>${content}<footer class="arcade-course-footer"><div>${button('Map editor · Level 10','editor','','arcade-button')}</div><small>Daily scores reset at midnight UTC. Weekly maps change Monday, midnight UTC. Practice and community maps do not award leaderboard results.</small></footer></section></main>`;
}
